"""Offline fixture generator; never needed by the build/tests/runtime.

Requires Python cryptography. Prints ONLY public material as a C++ header.
The ephemeral TEST private key is not serialized, logged, or installed.
These signatures exercise exact PSS parameters through a test-only bare-status
seam; the production pinned-root entry point must reject them.
"""
import base64
import textwrap

from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import padding, rsa


def varint(value):
    result = bytearray()
    while value >= 128:
        result.append((value & 127) | 128)
        value >>= 7
    result.append(value)
    return bytes(result)


def data(field, value):
    return varint((field << 3) | 2) + varint(len(value)) + value


key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
public = key.public_key().public_bytes(serialization.Encoding.DER, serialization.PublicFormat.PKCS1)
# Noncanonical-but-valid protobuf varint is intentional: verify EXACT bytes.
payload = b"\x08\x83\x00" + data(4, public) + data(7, b"test.invalid\0not-an-origin")
variants = {
    "PssSha1Salt20": (padding.PSS(mgf=padding.MGF1(hashes.SHA1()), salt_length=20), hashes.SHA1()),
    "PssSha1Salt0": (padding.PSS(mgf=padding.MGF1(hashes.SHA1()), salt_length=0), hashes.SHA1()),
    "PssSha1Salt32": (padding.PSS(mgf=padding.MGF1(hashes.SHA1()), salt_length=32), hashes.SHA1()),
    "PssSha1Mgf256Salt20": (padding.PSS(mgf=padding.MGF1(hashes.SHA256()), salt_length=20), hashes.SHA1()),
    "PssSha256Salt20": (padding.PSS(mgf=padding.MGF1(hashes.SHA256()), salt_length=20), hashes.SHA256()),
    "Pkcs1Sha1": (padding.PKCS1v15(), hashes.SHA1()),
}
values = {"PublicKey": public, "Payload": payload}
for name, (scheme, digest) in variants.items():
    signature = key.sign(payload, scheme, digest)
    key.public_key().verify(signature, payload, scheme, digest)
    values[name] = signature
print("#pragma once\n\n// SYNTHETIC TEST public key/signatures only. NEVER a production trust anchor.")
print("// Generated by generate_synthetic.py; private key discarded, not serialized.")
print("namespace EsvmCertificateSynthetic {")
for name, value in values.items():
    print(f"inline constexpr char {name}Base64[] =")
    lines = textwrap.wrap(base64.b64encode(value).decode(), 100)
    for i, line in enumerate(lines):
        print('    "' + line + '"' + (';' if i == len(lines) - 1 else ''))
print("} // namespace EsvmCertificateSynthetic")
